<script setup lang="ts">
import {computed,ref} from 'vue'
const products=[{id:1,name:'Coca-Cola',category:'Đồ uống',price:15000,art:'🥤',color:'#ff5b57'},{id:2,name:'Khoai tây Lay’s',category:'Snack',price:18000,art:'🍟',color:'#ffc531'},{id:3,name:'Choco Pie',category:'Bánh kẹo',price:10000,art:'🍫',color:'#6b5be6'},{id:4,name:'Cà phê',category:'Đồ uống',price:18000,art:'☕',color:'#12b3a4'}]
const categories=['Tất cả','Đồ uống','Snack','Bánh kẹo']; const category=ref('Tất cả'); const query=ref(''); const cart=ref<Record<number,number>>({}); const open=ref(false)
const filtered=computed(()=>products.filter(p=>(category.value==='Tất cả'||p.category===category.value)&&p.name.toLowerCase().includes(query.value.toLowerCase())))
const count=computed(()=>Object.values(cart.value).reduce((a,b)=>a+b,0)); const total=computed(()=>products.reduce((a,p)=>a+p.price*(cart.value[p.id]||0),0))
const money=(n:number)=>n.toLocaleString('vi-VN')+' đ'; function add(id:number){cart.value[id]=(cart.value[id]||0)+1} function remove(id:number){cart.value[id]=Math.max(0,(cart.value[id]||0)-1)}
</script>
<template>
<header><a class="logo" href="#">✳ DOP<span>MART.</span></a><nav><a href="#categories">Danh mục</a><a href="#products">Món ngon</a></nav><button @click="open=!open">Giỏ hàng · {{count}}</button></header>
<main><section class="hero"><div><small>✳ MINI MART — BIG HAPPY</small><h1>Shop <mark>happy.</mark><br>Live colorful.</h1><p>Món ngon ngay trong văn phòng. Nạp năng lượng, thêm niềm vui mỗi ngày.</p><a class="button" href="#products">Khám phá ngay ↗</a></div><div class="poster"><small>THE DOP EDIT / 01</small><strong>DOP<br>PICKS!</strong><div class="art">🥤 🍟</div></div></section>
<section id="categories"><small>01 / FIND YOUR FLAVOR</small><h2>Chọn vị của bạn.</h2><div class="categories"><button v-for="(c,i) in categories" :key="c" :style="{background:['#ffc531','#12b3a4','#ff5b57','#6b5be6'][i]}" :aria-pressed="category===c" @click="category=c">{{c}} ↗</button></div></section>
<section id="products"><small>02 / FRESH ON THE SHELF</small><h2>Mới lên kệ.</h2><label>Tìm món yêu thích <input v-model="query" placeholder="Tên sản phẩm"></label><div class="products"><article v-for="p in filtered" :key="p.id"><div class="picture" :style="{background:p.color}"><span>{{p.art}}</span></div><small>{{p.category}}</small><h3>{{p.name}}</h3><div class="buy"><b>{{money(p.price)}}</b><button :aria-label="'Thêm '+p.name" @click="add(p.id)">+</button></div></article></div><p v-if="!filtered.length">Không tìm thấy sản phẩm.</p></section>
<section class="spot"><small>03 / THE WEEKLY EDIT</small><h2>Good snacks.<br>Better breaks.</h2><a class="button" href="#products">Chọn món ngay ↗</a></section></main>
<footer>✳ DOP MART. — MINI MART, BIG HAPPY <p>Giao diện thử nghiệm · Dữ liệu minh họa</p></footer>
<aside v-if="open" aria-label="Giỏ hàng"><button @click="open=false">Đóng ×</button><h2>Giỏ hàng</h2><p v-if="!count">Giỏ hàng đang trống.</p><div v-for="p in products.filter(p=>cart[p.id])" :key="p.id" class="buy"><span>{{p.name}} × {{cart[p.id]}}</span><button @click="remove(p.id)">−</button><button @click="add(p.id)">+</button></div><h3>{{money(total)}}</h3></aside>
</template>
<style>
