eight:100px;font-size:20px}.categories button[aria-pressed=true]{outline:3px solid;outline-offset:4px}label{display:flex;align-items:center;gap:12px;margin:20px 0;flex-wrap:wrap}input{min-height:44px;border:2px solid;padding:10px;max-width:100%}article{background:white;border:2px solid;box-shadow:4px 4px;padding:12px;min-width:0;transition:transform .2s}article:hover{transform:translateY(-4px)}.picture{aspect-ratio:1.2;display:grid;place-items:center;border:2px solid;margin-bottom:14px;overflow:hidden}.picture span{font-size:clamp(50px,8vw,100px)}h3{font-size:20px;margin:8px 0}.buy{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:12px}.buy button{padding:6px 12px;min-width:44px}.spot{background:#ff5b57;border:3px solid;padding:40px;box-shadow:7px 7px}footer{background:#17140d;color:white;padding:36px;font-weight:800}footer p{font-weight:400;margin-top:12px}aside{position:fixed;z-index:10;right:0;top:0;height:100dvh;width:min(420px,100%);background:#f5efe2;border-left:3px solid;padding:24px;overflow:auto;box-shadow:-8px 0 0 #17140d}@media(max-width:760px){nav{display:none}main{padding:16px}.hero{grid-template-columns:1fr;gap:28px;padding:20px 0}.poster{min-height:300px;transform:none}.categories,.products{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.categories button{font-size:16px;min-height:76px}section{margin-bottom:48px}header{padding:12px}.logo{font-size:20px}.spot{padding:24px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*::before,*::after{transition:none!important;animation:none!important}}
</style>